// Cities grouped by state code, for `--state=<CODE>` generation.
export const CITIES_BY_STATE = Object.values(CITY_PROFILES).reduce((acc, p) => {
  (acc[p.stateCode] = acc[p.stateCode] || []).push(p.citySlug);
  return acc;
}, /** @type {Record<string,string[]>} */ ({}));
